// Static reference data, generated by scripts/build-data.py from pymatgen's bundled tables.
import shannonRaw from "../data/shannon.json";
import bvRaw from "../data/bvparams.json";
import elementsRaw from "../data/elements.json";
import vestaRaw from "../data/vesta_cutoffs.json";
import idealRaw from "../data/ideal_polyhedra.json";

export interface ShannonEntry {
  el: string;
  ox: number;
  cn: number;
  cnLabel: string; // "VI", "IVSQ", "IVPY", ...
  spin: "" | "HS" | "LS";
  crystal: number;
  ionic: number;
}

export interface ElementInfo {
  Z: number;
  X: number | null; // Pauling electronegativity
  r: number | null; // atomic radius (Å)
  ox: number[]; // common oxidation states
  icsd: number[];
  col: [number, number, number];
}

export interface IdealPolyhedron {
  sym: string;
  name: string;
  cn: number;
  iupac: string | null;
  pts: [number, number, number][];
}

export const SHANNON: ShannonEntry[] = (shannonRaw as [string, number, number, string, string, number, number][]).map(
  ([el, ox, cn, cnLabel, spin, crystal, ionic]) => ({ el, ox, cn, cnLabel, spin: spin as ShannonEntry["spin"], crystal, ionic }),
);

export const ELEMENTS = elementsRaw as unknown as Record<string, ElementInfo>;
export const BV_PARAMS = bvRaw as unknown as Record<string, [number, number]>; // [r, c] Brese & O'Keeffe 1991
export const VESTA_CUTOFFS = vestaRaw as Record<string, number>;
export const IDEAL_POLYHEDRA = (idealRaw as IdealPolyhedron[]).filter((p) => p.sym !== "DDPN:8");

export const ELEMENT_SYMBOLS = Object.keys(ELEMENTS).sort((a, b) => ELEMENTS[a].Z - ELEMENTS[b].Z);

export function elementColor(el: string): [number, number, number] {
  return ELEMENTS[el]?.col ?? [200, 200, 200];
}

export const ROMAN = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV"];
export function roman(n: number): string {
  return ROMAN[n] ?? String(n);
}

export function formatIon(el: string, ox: number | null | undefined): string {
  if (ox === null || ox === undefined || ox === 0) return el;
  const mag = Math.abs(ox);
  const magStr = Number.isInteger(mag) ? (mag === 1 ? "" : String(mag)) : mag.toFixed(2);
  return `${el}${magStr}${ox > 0 ? "+" : "−"}`;
}

